parts.solution:
def distance(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))


def predict(train_x, train_y, point, k=3):
    ranked = sorted(
        (distance(x, point), y) for x, y in zip(train_x, train_y)
    )[:k]
    counts = Counter(label for _, label in ranked)
    best = max(counts.values())
    tied = {label for label, n in counts.items() if n == best}
    for _, label in ranked:
        if label in tied:
            return label

def fit_scaler(train_x):
    columns = list(zip(*train_x))
    return [(min(c), max(c)) for c in columns]


def scale(point, ranges):
    return [
        0.0 if hi == lo else (v - lo) / (hi - lo)
        for v, (lo, hi) in zip(point, ranges)
    ]

def accuracy(train_x, train_y, test_x, test_y, k):
    if not test_x:
        raise ValueError('test set is empty')
    ranges = fit_scaler(train_x)
    scaled_train = [scale(x, ranges) for x in train_x]
    hits = sum(
        predict(scaled_train, train_y, scale(x, ranges), k) == y
        for x, y in zip(test_x, test_y)
    )
    return hits / len(test_x)


def best_k(train_x, train_y, test_x, test_y, ks):
    best, best_score = None, -1.0
    for k in sorted(ks):
        score = accuracy(train_x, train_y, test_x, test_y, k)
        if score > best_score:
            best, best_score = k, score
    return best

