parts.solution:
def _normalise(v):
    norm = math.sqrt(sum(x * x for x in v))
    if norm == 0:
        raise ValueError('zero vector')
    return [x / norm for x in v]


class VectorIndex:
    def __init__(self, dim):
        self.dim = dim
        self.items = {}

    def add(self, item_id, vector, metadata=None):
        if len(vector) != self.dim:
            raise ValueError(f'expected {self.dim} dims, got {len(vector)}')
        self.items[item_id] = (_normalise(vector), metadata or {})

    def search(self, query, k=5):
        q = _normalise(query)
        scored = (
            (sum(a * b for a, b in zip(q, v)), item_id)
            for item_id, (v, _) in self.items.items()
        )
        return [(i, s) for s, i in heapq.nlargest(k, scored)]

def search(self, query, k=5, where=None):
    q = _normalise(query)
    where = where or {}
    scored = (
        (sum(a * b for a, b in zip(q, v)), item_id)
        for item_id, (v, meta) in self.items.items()
        if all(meta.get(key) == val for key, val in where.items())
    )
    return [(i, s) for s, i in heapq.nlargest(k, scored)]

def delete(self, item_id):
    return self.items.pop(item_id, None) is not None

def add(self, item_id, vector, metadata=None):
    if len(vector) != self.dim:
        raise ValueError(f'expected {self.dim} dims, got {len(vector)}')
    self.delete(item_id)
    v = _normalise(vector)
    self.items[item_id] = (v, metadata or {})
    if getattr(self, 'buckets', None):
        self.buckets[self._nearest(v)].add(item_id)

def delete(self, item_id):
    for bucket in getattr(self, 'buckets', {}).values():
        bucket.discard(item_id)
    return self.items.pop(item_id, None) is not None

def build_buckets(self, centroids):
    self.centroids = [_normalise(c) for c in centroids]
    self.buckets = {i: set() for i in range(len(self.centroids))}
    for item_id, (v, _) in self.items.items():
        self.buckets[self._nearest(v)].add(item_id)

def _nearest(self, v, n=1):
    sims = [
        (sum(a * b for a, b in zip(c, v)), i)
        for i, c in enumerate(self.centroids)
    ]
    best = [i for _, i in heapq.nlargest(n, sims)]
    return best[0] if n == 1 else best

def search_approx(self, query, k=5, n_probe=1):
    q = _normalise(query)
    ids = set().union(*(self.buckets[i] for i in self._nearest(q, n_probe)))
    scored = (
        (sum(a * b for a, b in zip(q, self.items[i][0])), i) for i in ids
    )
    return [(i, s) for s, i in heapq.nlargest(k, scored)]

