import json


def count_tokens(text: str) -> int:
    ...


def pack_chunks(chunks, budget):
    """chunks: list of dicts with "id", "text" and "score"."""
    ...

parts.solution:
def count_tokens(text):
    return len(text.split())


def pack_chunks(chunks, budget):
    chosen, used = [], 0
    for chunk in sorted(chunks, key=lambda c: c["score"], reverse=True):
        cost = count_tokens(chunk["text"])
        if used + cost <= budget:
            chosen.append(chunk["id"])
            used += cost
    return chosen

def build_prompt(system, question, chunks, window, reserve_for_answer):
    budget = (
        window
        - reserve_for_answer
        - count_tokens(system)
        - count_tokens(question)
    )
    if budget < 0:
        raise ValueError("system prompt and question do not fit the window")
    by_id = {c["id"]: c for c in chunks}
    ids = pack_chunks(chunks, budget)
    context = "\n".join(f"[{i}] {by_id[i]['text']}" for i in ids)
    return f"{system}\n\n{context}\n\nQuestion: {question}"

def parse_answer(raw, allowed_ids):
    text = raw.strip()
    if text.startswith("```"):
        text = text.split("\n", 1)[1] if "\n" in text else ""
        if text.rstrip().endswith("```"):
            text = text.rstrip()[:-3]
    data = json.loads(text)
    if not isinstance(data, dict):
        raise ValueError("reply is not a JSON object")
    answer = data.get("answer")
    sources = data.get("sources")
    if not isinstance(answer, str) or not answer.strip():
        raise ValueError("missing answer")
    if not isinstance(sources, list) or not all(isinstance(s, str) for s in sources):
        raise ValueError("sources must be a list of strings")
    unknown = set(sources) - set(allowed_ids)
    if unknown:
        raise ValueError(f"unknown sources: {sorted(unknown)}")
    return answer, sources

