import statistics


def mean_diff(control, variant):
    ...


def bootstrap_ci(control, variant, n_resamples=2000, alpha=0.05, seed=0):
    ...

parts.solution:
def mean_diff(control, variant):
    return statistics.fmean(variant) - statistics.fmean(control)


def bootstrap_ci(control, variant, n_resamples=2000, alpha=0.05, seed=0):
    if not control or not variant:
        raise ValueError("both groups need data")
    rng = random.Random(seed)
    diffs = sorted(
        mean_diff(
            rng.choices(control, k=len(control)),
            rng.choices(variant, k=len(variant)),
        )
        for _ in range(n_resamples)
    )
    low = diffs[int(alpha / 2 * n_resamples)]
    high = diffs[int((1 - alpha / 2) * n_resamples) - 1]
    return low, high

def permutation_p_value(control, variant, n_permutations=2000, seed=0):
    rng = random.Random(seed)
    observed = abs(mean_diff(control, variant))
    pool = list(control) + list(variant)
    n = len(control)
    count = 0
    for _ in range(n_permutations):
        rng.shuffle(pool)
        if abs(mean_diff(pool[:n], pool[n:])) >= observed:
            count += 1
    return (count + 1) / (n_permutations + 1)

def decide(control, variant, min_effect, alpha=0.05, seed=0):
    low, high = bootstrap_ci(control, variant, alpha=alpha, seed=seed)
    p = permutation_p_value(control, variant, seed=seed)
    if p < alpha and low >= min_effect:
        return "ship"
    if -min_effect < low and high < min_effect:
        return "no difference"
    return "inconclusive"

