import bisect
import hashlib


def stable_hash(value: str) -> int:
    ...


class HashRing:
    def __init__(self, nodes=(), replicas=100):
        ...

parts.solution:
def stable_hash(value):
    return int(hashlib.md5(value.encode("utf-8")).hexdigest(), 16)


class HashRing:
    def __init__(self, nodes=(), replicas=100):
        self.replicas = replicas
        self._positions = []
        self._owner = {}
        for node in nodes:
            self.add(node)

    def add(self, node):
        for i in range(self.replicas):
            pos = stable_hash(f"{node}#{i}")
            self._owner[pos] = node
            bisect.insort(self._positions, pos)

    def remove(self, node):
        for i in range(self.replicas):
            pos = stable_hash(f"{node}#{i}")
            if self._owner.pop(pos, None) is not None:
                self._positions.remove(pos)

    def get(self, key):
        if not self._positions:
            raise LookupError("ring is empty")
        i = bisect.bisect(self._positions, stable_hash(key))
        return self._owner[self._positions[i % len(self._positions)]]

def moved_fraction(keys, before, after):
    moved = sum(1 for k in keys if before.get(k) != after.get(k))
    return moved / len(keys)


def modulo_moved_fraction(keys, nodes_before, nodes_after):
    def owner(key, nodes):
        return nodes[stable_hash(key) % len(nodes)]

    moved = sum(1 for k in keys if owner(k, nodes_before) != owner(k, nodes_after))
    return moved / len(keys)

from collections import Counter


def load_spread(ring, keys):
    nodes = set(ring._owner.values())
    counts = Counter(ring.get(k) for k in keys)
    loads = [counts.get(n, 0) for n in nodes]
    if min(loads) == 0:
        return float("inf")
    return max(loads) / min(loads)
